css:
.ss-acc__i{border-top:1px solid var(--line)}
.ss-acc__t{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;padding:16px 0;cursor:pointer;list-style:none;font:400 15px/1.5 var(--font-body);color:var(--body-text)}
.ss-acc__t::-webkit-details-marker{display:none}
.ss-acc__t::after{content:"+";flex:none;font:400 22px/1.4 var(--font-body);color:var(--accent);transition:transform .18s ease}
.ss-acc__i[open] .ss-acc__t::after{transform:rotate(45deg)}
.ss-acc__t:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.ss-acc__i[open] .ss-acc__t{padding-bottom:0}
.ss-acc__d{font-size:15px;line-height:1.5;color:var(--muted);margin:0;padding:0 0 16px}
@media (prefers-reduced-motion: reduce){.ss-acc__t::after{transition:none}}
